<?php
declare(strict_types=1);require_once __DIR__.'/bootstrap.php';learning_require_login();$uid=learning_user_id();$pdo=learning_pdo();$message='';if($_SERVER['REQUEST_METHOD']==='POST'){$lid=(int)($_POST['lesson_id']??0);$note=trim((string)($_POST['note']??''));if($lid>0&&$note!==''){$s=$pdo->prepare("INSERT INTO learning_notes(user_id,lesson_id,note) VALUES(?,?,?) ON DUPLICATE KEY UPDATE note=VALUES(note),updated_at=CURRENT_TIMESTAMP");$s->execute([$uid,$lid,$note]);$message='Note saved.';}}
$s=$pdo->prepare("SELECT n.*,l.title FROM learning_notes n JOIN learning_lessons l ON l.id=n.lesson_id WHERE n.user_id=? ORDER BY n.updated_at DESC");$s->execute([$uid]);$rows=$s->fetchAll();
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Notes</title><style>body{margin:0;background:#080a10;color:#fff;font-family:Inter,system-ui}.wrap{max-width:850px;margin:auto;padding:30px 18px}.card{padding:15px;border:1px solid #fff1;border-radius:12px;background:#10151e;margin:8px 0}.input{width:100%;box-sizing:border-box;background:#07090d;color:#fff;border:1px solid #fff2;border-radius:8px;padding:10px;margin:5px 0}.btn{padding:9px 12px;border:0;border-radius:8px;background:#8b5cf6;color:#fff;font-size:8px}.small{color:#788398;font-size:8px}</style></head><body><div class=wrap><a href="/creator-ai/learning/" style="color:#a78bfa;font-size:8px">← Learning Hub</a><h1>📝 Notes</h1><div class=card><form method=post><input class=input name=lesson_id placeholder="Lesson ID"><textarea class=input name=note rows=4 placeholder="Write your note..."></textarea><button class=btn>Save Note</button></form><?php if($message):?><p class=small><?=eh($message)?></p><?php endif;?></div><?php foreach($rows as $r):?><div class=card><strong style="font-size:10px"><?=eh($r['title'])?></strong><p class=small><?=nl2br(eh($r['note']))?></p></div><?php endforeach;?></div></body></html>